function v2_seo_maldives_hotel_links(): array
{
    return array_map(
        static fn(array $entry): array => ['label' => $entry['label'], 'href' => $entry['href']],
        v2_seo_maldives_hotel_manifest()
    );
}

function v2_seo_maldives_hotel_records(): array
{
    $records = [];
    $seenFunctions = [];
    $seenPaths = [];
    foreach (v2_seo_maldives_hotel_manifest() as $entry) {
        $file = trim((string)($entry['file'] ?? ''));
        $function = trim((string)($entry['function'] ?? ''));
        $href = trim((string)($entry['href'] ?? ''));
        if ($file === '' || $function === '' || $href === '') {
            throw new InvalidArgumentException('Maldives hotel manifest entry is incomplete');
        }
        if (isset($seenFunctions[$function]) || isset($seenPaths[$href])) {
            throw new InvalidArgumentException('Maldives hotel manifest contains duplicate identity');
        }
        $seenFunctions[$function] = true;
        $seenPaths[$href] = true;

        $absolute = __DIR__ . '/' . $file;
        if (!is_file($absolute)) throw new InvalidArgumentException('Maldives hotel manifest file is missing: ' . $file);
        require_once $absolute;
        if (!function_exists($function)) throw new InvalidArgumentException('Maldives hotel manifest function is missing: ' . $function);
        $record = $function();
        if (($record['path'] ?? '') !== $href) {
            throw new InvalidArgumentException('Maldives hotel manifest path does not match content record: ' . $function);
        }
        $records[] = $record;
    }
    return $records;
}
